const DESIGNS=[{"id": "AI-001", "title": "สวนทรอปิคอลคอร์ตกลางบ้าน", "style": "ทรอปิคอล", "image": "data:image/jpeg;base64,"}, {"id": "AI-002", "title": "สวนหลังบ้านทรอปิคอล", "style": "ทรอปิคอล", "image": "data:image/jpeg;base64,"}, {"id": "AI-003", "title": "บอร์ดออกแบบสวนทรอปิคอล", "style": "ทรอปิคอล", "image": "data:image/jpeg;base64,"}, {"id": "AI-004", "title": "สวนมินิมอลโมเดิร์น", "style": "มินิมอลโมเดิร์น", "image": "data:image/jpeg;base64,"}, {"id": "AI-005", "title": "แบบมืออาชีพมินิมอล", "style": "มินิมอลโมเดิร์น", "image": "data:image/jpeg;base64,"}];
const PLANTS=[{"id": "PL001", "name": "มอนสเตอร่า", "category": "ไม้ใบ", "light": "ร่ม/รำไร", "water": "มาก", "price": 350, "stock": 24}, {"id": "PL002", "name": "กล้วยน้ำว้า", "category": "ไม้ประธาน", "light": "แดดจัด", "water": "มาก", "price": 180, "stock": 18}, {"id": "PL003", "name": "หมากเขียว", "category": "ปาล์ม", "light": "รำไร", "water": "มาก", "price": 900, "stock": 12}, {"id": "PL004", "name": "ไทรใบสัก", "category": "ไม้ประธาน", "light": "รำไร", "water": "ปานกลาง", "price": 2500, "stock": 9}, {"id": "PL005", "name": "โมกพวง", "category": "ไม้พุ่ม", "light": "แดดจัด", "water": "ปานกลาง", "price": 350, "stock": 45}, {"id": "PL006", "name": "ลิ้นมังกร", "category": "ไม้ใบ", "light": "รำไร", "water": "น้อย", "price": 180, "stock": 36}, {"id": "PL007", "name": "อากาเว่", "category": "ไม้อวบน้ำ", "light": "แดดจัด", "water": "น้อย", "price": 350, "stock": 21}, {"id": "PL008", "name": "เฟิร์นบอสตัน", "category": "เฟิร์น", "light": "ร่ม/รำไร", "water": "มาก", "price": 150, "stock": 32}];
const app=document.getElementById('app'),sidebar=document.getElementById('sidebar');
const load=(k,f)=>JSON.parse(localStorage.getItem(k)||JSON.stringify(f));
const save=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let customers=load('mobile_customers',[{id:'CUS-001',name:'สมชาย ใจดี',phone:'089-111-2233',address:'นนทบุรี'}]);
let projects=load('mobile_projects',[{id:'PRJ-001',name:'สวนหลังบ้าน',customer:'สมชาย ใจดี',style:'ทรอปิคอล',status:'กำลังออกแบบ',budget:150000}]);
let boq=load('mobile_boq',[]);

document.getElementById('menuBtn').onclick=()=>sidebar.classList.toggle('open');
sidebar.querySelectorAll('button').forEach(b=>b.onclick=()=>{sidebar.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');sidebar.classList.remove('open');render(b.dataset.page)});

function render(page){
 if(page==='dashboard') return dashboard();
 if(page==='customers') return customersPage();
 if(page==='projects') return projectsPage();
 if(page==='gallery') return galleryPage();
 if(page==='plants') return plantsPage();
 if(page==='templates') return templatesPage();
 if(page==='boq') return boqPage();
 if(page==='settings') return settingsPage();
}
function dashboard(){
 const total=projects.reduce((s,p)=>s+(+p.budget||0),0);
 app.innerHTML=`<section class="hero"><h2>ภาพรวมธุรกิจจัดสวน</h2><p>บริหารลูกค้า โครงการ แบบสวน และ BOQ ในที่เดียว</p></section>
 <section class="stats"><div class="stat">ลูกค้า<strong>${customers.length}</strong></div><div class="stat">โครงการ<strong>${projects.length}</strong></div><div class="stat">แบบ AI<strong>${DESIGNS.length}</strong></div><div class="stat">มูลค่าโครงการ<strong>${total.toLocaleString('th-TH')} ฿</strong></div></section>
 <section class="card"><h3>โครงการล่าสุด</h3>${projects.map(p=>`<p><b>${p.name}</b> — ${p.customer} • ${p.status}</p>`).join('')}</section>`;
}
function customersPage(){
 app.innerHTML=`<div class="pagehead"><h2>ลูกค้า CRM</h2><button onclick="customerForm()">+ เพิ่มลูกค้า</button></div><div class="card tablewrap"><table><thead><tr><th>รหัส</th><th>ชื่อ</th><th>โทรศัพท์</th><th>ที่อยู่</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr><td>${c.id}</td><td>${c.name}</td><td>${c.phone}</td><td>${c.address||'-'}</td><td><button onclick="deleteCustomer('${c.id}')">ลบ</button></td></tr>`).join('')}</tbody></table></div>`;
}
function customerForm(){
 modal(`<h3>เพิ่มลูกค้า</h3><label>ชื่อ<input id="cname"></label><label>โทรศัพท์<input id="cphone"></label><label>ที่อยู่<textarea id="caddress"></textarea></label><button onclick="addCustomer()">บันทึก</button>`);
}
function addCustomer(){customers.unshift({id:'CUS-'+Date.now().toString().slice(-5),name:cname.value,phone:cphone.value,address:caddress.value});save('mobile_customers',customers);closeModal();customersPage()}
function deleteCustomer(id){if(confirm('ลบลูกค้ารายนี้?')){customers=customers.filter(x=>x.id!==id);save('mobile_customers',customers);customersPage()}}
function projectsPage(){
 app.innerHTML=`<div class="pagehead"><h2>โครงการ</h2><button onclick="projectForm()">+ สร้างโครงการ</button></div><div class="card tablewrap"><table><thead><tr><th>รหัส</th><th>โครงการ</th><th>ลูกค้า</th><th>สไตล์</th><th>สถานะ</th><th>งบประมาณ</th><th></th></tr></thead><tbody>${projects.map(p=>`<tr><td>${p.id}</td><td>${p.name}</td><td>${p.customer}</td><td>${p.style}</td><td>${p.status}</td><td>${(+p.budget).toLocaleString('th-TH')}</td><td><button onclick="deleteProject('${p.id}')">ลบ</button></td></tr>`).join('')}</tbody></table></div>`;
}
function projectForm(){modal(`<h3>สร้างโครงการ</h3><label>ชื่อโครงการ<input id="pname"></label><label>ลูกค้า<input id="pcustomer"></label><label>สไตล์<select id="pstyle"><option>ทรอปิคอล</option><option>มินิมอลโมเดิร์น</option><option>ญี่ปุ่น</option></select></label><label>งบประมาณ<input id="pbudget" type="number"></label><button onclick="addProject()">บันทึก</button>`)}
function addProject(){projects.unshift({id:'PRJ-'+Date.now().toString().slice(-5),name:pname.value,customer:pcustomer.value,style:pstyle.value,status:'ลูกค้าใหม่',budget:+pbudget.value||0});save('mobile_projects',projects);closeModal();projectsPage()}
function deleteProject(id){if(confirm('ลบโครงการนี้?')){projects=projects.filter(x=>x.id!==id);save('mobile_projects',projects);projectsPage()}}
function galleryPage(){
 app.innerHTML=`<div class="pagehead"><h2>AI Gallery</h2></div><div class="grid gallery">${DESIGNS.map(d=>`<article class="card"><img src="${d.image}"><span class="badge">${d.style}</span><h3>${d.title}</h3><button onclick="useTemplate('${d.style}')">ใช้เป็นต้นแบบ</button></article>`).join('')}</div>`;
}
function plantsPage(){
 app.innerHTML=`<div class="pagehead"><h2>ฐานข้อมูลต้นไม้</h2></div><div class="card tablewrap"><table><thead><tr><th>รหัส</th><th>ชื่อ</th><th>หมวด</th><th>แสง</th><th>น้ำ</th><th>ราคา</th><th>สต็อก</th><th></th></tr></thead><tbody>${PLANTS.map(p=>`<tr><td>${p.id}</td><td>${p.name}</td><td>${p.category}</td><td>${p.light}</td><td>${p.water}</td><td>${p.price}</td><td>${p.stock}</td><td><button onclick="addPlantToBoq('${p.id}')">เพิ่ม BOQ</button></td></tr>`).join('')}</tbody></table></div>`;
}
function templatesPage(){app.innerHTML=`<div class="pagehead"><h2>แบบสวน</h2></div><div class="grid">${['ทรอปิคอล','มินิมอลโมเดิร์น','ญี่ปุ่น','อังกฤษ','บาหลี','สวนหิน'].map(s=>`<article class="card"><h3>${s}</h3><p>แบบสวนสำเร็จรูปสำหรับเริ่มต้นโครงการ</p><button onclick="useTemplate('${s}')">เลือกแบบ</button></article>`).join('')}</div>`}
function useTemplate(style){alert('เลือกแบบ '+style+' แล้ว สามารถนำไปสร้างโครงการหรือ BOQ ต่อได้')}
function addPlantToBoq(id){const p=PLANTS.find(x=>x.id===id);const old=boq.find(x=>x.id===id);if(old)old.qty++;else boq.push({...p,qty:1});save('mobile_boq',boq);alert('เพิ่ม '+p.name+' เข้า BOQ แล้ว')}
function boqPage(){
 const total=boq.reduce((s,x)=>s+x.qty*x.price,0);
 app.innerHTML=`<div class="pagehead"><h2>BOQ</h2><button onclick="clearBoq()">ล้าง BOQ</button></div><div class="card tablewrap"><table><thead><tr><th>รายการ</th><th>จำนวน</th><th>ราคา/หน่วย</th><th>รวม</th></tr></thead><tbody>${boq.map(x=>`<tr><td>${x.name}</td><td><input type="number" value="${x.qty}" min="1" onchange="setQty('${x.id}',this.value)"></td><td>${x.price}</td><td>${(x.qty*x.price).toLocaleString('th-TH')}</td></tr>`).join('')}</tbody></table><h3>รวม ${total.toLocaleString('th-TH')} บาท</h3></div>`;
}
function setQty(id,q){const x=boq.find(i=>i.id===id);x.qty=+q||1;save('mobile_boq',boq);boqPage()}
function clearBoq(){if(confirm('ล้าง BOQ ทั้งหมด?')){boq=[];save('mobile_boq',boq);boqPage()}}
function settingsPage(){app.innerHTML=`<div class="pagehead"><h2>ตั้งค่า</h2></div><div class="card"><label>ชื่อบริษัท<input value="Landscape Studio"></label><label>โทรศัพท์<input></label><label>ที่อยู่<textarea></textarea></label><button>บันทึก</button><p>เวอร์ชันนี้เก็บข้อมูลในเครื่องและใช้ GitHub Pages ได้ทันที</p></div>`}
function modal(html){const m=document.createElement('div');m.id='modal';m.className='modal';m.innerHTML=`<div class="card">${html}<button onclick="closeModal()">ปิด</button></div>`;document.body.appendChild(m)}
function closeModal(){document.getElementById('modal')?.remove()}
dashboard();
